CREATE TABLE field_backfill_verification (verified boolean PRIMARY KEY CHECK (verified));
CREATE FUNCTION invalidate_field_verification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $$
BEGIN
  DELETE FROM public.field_backfill_verification;
  RETURN NULL;
END $$;
CREATE TRIGGER field_data_changed AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON person FOR EACH STATEMENT EXECUTE FUNCTION invalidate_field_verification();
