CREATE TABLE staff_read_audit (id serial PRIMARY KEY, actor_member_id int NOT NULL, status text NOT NULL CHECK (status IN ('DISCLOSED', 'FAILED')), action text NOT NULL, scope text, count int NOT NULL CHECK (count >= 0), read_at timestamptz NOT NULL DEFAULT now());
INSERT INTO permission(code, description, scope, is_sensitive) VALUES ('audit.staff_reads.view', 'Read the staff access history', 'global', true);
INSERT INTO role_permission (role_code, code) VALUES ('GROUP_LEADER', 'audit.staff_reads.view'), ('GROUP_CO_LEADER', 'audit.staff_reads.view');
CREATE VIEW recent_staff_reads WITH (security_barrier=true) AS SELECT id, actor_member_id AS "actorMemberId", action, status, scope, count, read_at AS "readAt" FROM staff_read_audit ORDER BY id DESC LIMIT 200;
COMMIT;
